        InteractionResult type = super.mobInteract(player, hand);
        if (itemstack.is(AMTagRegistry.MANED_WOLF_STENCH_FOODS) && !this.isShaking() && this.getMainHandItem().isEmpty()) {
            this.usePlayerItem(player, hand, itemstack);
            eatItemEffect(itemstack);
            this.setShakingTime(100 + random.nextInt(30));
            return InteractionResult.SUCCESS;
        } else {
            return type;
        }
    }

    private void eatItemEffect(ItemStack heldItemMainhand) {
        for (int i = 0; i < 2 + random.nextInt(2); i++) {
            double d2 = this.random.nextGaussian() * 0.02D;
            double d0 = this.random.nextGaussian() * 0.02D;
            double d1 = this.random.nextGaussian() * 0.02D;
            float radius = this.getBbWidth() * 0.65F;
            float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
            double extraX = radius * Mth.sin(Mth.PI + angle);
            double extraZ = radius * Mth.cos(angle);
            ParticleOptions data = new ItemParticleOption(ParticleTypes.ITEM, heldItemMainhand);
            if (heldItemMainhand.getItem() instanceof BlockItem) {
                data = new BlockParticleOption(ParticleTypes.BLOCK, ((BlockItem) heldItemMainhand.getItem()).getBlock().defaultBlockState());
            }
            this.level().addParticle(data, this.getX() + extraX, this.getY() + this.getBbHeight() * 0.6F, this.getZ() + extraZ, d0, d1, d2);
        }
    }

    public void tick() {
        super.tick();
        prevEarPitch = this.getEarPitch();
        prevEarYaw = this.getEarYaw();
        prevDanceProgress = danceProgress;
        prevShakeProgress = shakeProgress;
        if (!this.level().isClientSide) {
            updateEars();
        }
        boolean dance = isDancing();
        if (this.jukeboxPosition == null || !this.jukeboxPosition.closerToCenterThan(this.position(), 15) || !this.level().getBlockState(this.jukeboxPosition).is(Blocks.JUKEBOX)) {
            this.isJukeboxing = false;
            this.setDancing(false);
            this.jukeboxPosition = null;
        }
        if (dance && danceProgress < 5F) {
            danceProgress++;
        }
        if (!dance && danceProgress > 0F) {
            danceProgress--;
        }
        if (this.isShaking() && shakeProgress < 5F) {
            shakeProgress++;
        }
        if (!this.isShaking() && shakeProgress > 0F) {
            shakeProgress--;
        }
        if (this.isShaking()) {
            this.setShakingTime(this.getShakingTime() - 1);
            if (this.level().isClientSide) {
                double d0 = this.random.nextGaussian() * 0.02D;
                double d1 = 0.05F + this.random.nextGaussian() * 0.02D;
                double d2 = this.random.nextGaussian() * 0.02D;
                this.level().addParticle(AMParticleRegistry.SMELLY.get(), this.getRandomX(0.7F), this.getY(0.6F), this.getRandomZ(0.7F), d0, d1, d2);
            }else{
                attractAnimals();
                findAnthill();
                if(this.nearestAnthill != null){
                    pollinateAnthill();
                }
            }
        }
    }

    private void updateEars() {
        final float pitchDist = Math.abs(targetPitch - this.getEarPitch());
        final float yawDist = Math.abs(targetYaw - this.getEarYaw());
        if (earCooldown <= 0 && this.random.nextInt(30) == 0 && pitchDist <= 0.1F && yawDist <= 0.1F) {
            targetPitch = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
            targetYaw = Mth.clamp(random.nextFloat() * 60F - 30, -30, 30);
            earCooldown = 8 + random.nextInt(15);
        }

        if (pitchDist > 0.1F) {
            if (this.getEarPitch() < this.targetPitch) {
                this.setEarPitch(this.getEarPitch() + Math.min(pitchDist, 4F));
            }
            if (this.getEarPitch() > this.targetPitch) {
                this.setEarPitch(this.getEarPitch() - Math.min(pitchDist, 4F));
            }
        }

        if (yawDist > 0.1F) {
            if (this.getEarYaw() < this.targetYaw) {
                this.setEarYaw(this.getEarYaw() + Math.min(yawDist, 4F));
            }
            if (this.getEarYaw() > this.targetYaw) {
                this.setEarYaw(this.getEarYaw() - Math.min(yawDist, 4F));
            }
        }

        if (earCooldown > 0) {
            earCooldown--;
        }
    }

    public boolean isFood(ItemStack stack) {
        return !stack.is(AMTagRegistry.MANED_WOLF_STENCH_FOODS) && allFoods.test(stack);
    }

    public void travel(Vec3 vec3d) {
        if (this.isDancing() || danceProgress > 0) {
            if (this.getNavigation().getPath() != null) {
                this.getNavigation().stop();
            }
            vec3d = Vec3.ZERO;
        }
        super.travel(vec3d);
    }

    @Override
    public boolean canTargetItem(ItemStack stack) {
        return allFoods.test(stack) && !this.isShaking();
    }

    @Override
    public void onGetItem(ItemEntity e) {
        eatItemEffect(e.getItem());
        if (e.getItem().is(AMTagRegistry.MANED_WOLF_STENCH_FOODS)) {
            this.setShakingTime(100 + random.nextInt(30));
        }
    }

    @Nullable
    @Override
    public AgeableMob getBreedOffspring(ServerLevel serverWorld, AgeableMob ageableEntity) {
        return AMEntityRegistry.MANED_WOLF.get().create(serverWorld);
    }

    @OnlyIn(Dist.CLIENT)
    public void setRecordPlayingNearby(BlockPos pos, boolean isPartying) {
        AlexsMobs.sendMSGToServer(new MessageStartDancing(this.getId(), isPartying, pos));
        this.setDancing(isPartying);
        if (isPartying) {
            this.setJukeboxPos(pos);
        } else {
            this.setJukeboxPos(null);
        }
    }

    public boolean isEnder() {
        String s = ChatFormatting.stripFormatting(this.getName().getString());
        return s != null && (s.toLowerCase().contains("plummet") || s.toLowerCase().contains("ender"));
    }

}

package com.github.alexthe666.alexsmobs.entity.ai;

import com.github.alexthe666.alexsmobs.entity.ITargetsDroppedItems;
import com.google.common.base.Predicate;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.ai.goal.target.TargetGoal;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import javax.annotation.Nullable;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumSet;
import java.util.List;

public class CreatureAITargetItems<T extends ItemEntity> extends TargetGoal {
    protected final CreatureAITargetItems.Sorter theNearestAttackableTargetSorter;
    protected final Predicate<? super ItemEntity> targetEntitySelector;
    protected int executionChance;
    protected boolean mustUpdate;
    protected ItemEntity targetEntity;
    protected ITargetsDroppedItems hunter;
    private final int tickThreshold;
    private float radius = 9F;
    private int walkCooldown = 0;

    public CreatureAITargetItems(PathfinderMob creature, boolean checkSight) {
        this(creature, checkSight, false);
        this.setFlags(EnumSet.of(Goal.Flag.MOVE));
    }

    public CreatureAITargetItems(PathfinderMob creature, boolean checkSight, int tickThreshold) {
        this(creature, checkSight, false, tickThreshold, 9);
        this.setFlags(EnumSet.of(Goal.Flag.MOVE));
    }


    public CreatureAITargetItems(PathfinderMob creature, boolean checkSight, boolean onlyNearby) {
        this(creature, 10, checkSight, onlyNearby, null, 0);
    }

    public CreatureAITargetItems(PathfinderMob creature, boolean checkSight, boolean onlyNearby, int tickThreshold, int radius) {
        this(creature, 10, checkSight, onlyNearby, null, tickThreshold);
        this.radius = radius;
    }


    public CreatureAITargetItems(PathfinderMob creature, int chance, boolean checkSight, boolean onlyNearby, @Nullable final Predicate<? super T> targetSelector, int ticksExisted) {
        super(creature, checkSight, onlyNearby);
        this.executionChance = chance;
        this.tickThreshold = ticksExisted;
        this.hunter = (ITargetsDroppedItems) creature;
        this.theNearestAttackableTargetSorter = new CreatureAITargetItems.Sorter(creature);
        this.targetEntitySelector = new Predicate<ItemEntity>() {
            @Override
            public boolean apply(@Nullable ItemEntity item) {
                ItemStack stack = item.getItem();
                return !stack.isEmpty()  && hunter.canTargetItem(stack) && item.tickCount > tickThreshold;
            }
        };
        this.setFlags(EnumSet.of(Goal.Flag.MOVE));
    }

    @Override
    public boolean canUse() {
        if (this.mob.isPassenger() || mob.isVehicle() && mob.getControllingPassenger() != null) {
            return false;
        }
        if(!mob.getItemInHand(InteractionHand.MAIN_HAND).isEmpty()){
            return false;
        }
        if (!this.mustUpdate) {
            long worldTime = this.mob.level().getGameTime() % 10;
            if (this.mob.getNoActionTime() >= 100 && worldTime != 0) {
                return false;
            }
            if (this.mob.getRandom().nextInt(this.executionChance) != 0 && worldTime != 0) {
                return false;
            }
        }
        List<ItemEntity> list = this.mob.level().getEntitiesOfClass(ItemEntity.class, this.getTargetableArea(this.getFollowDistance()), this.targetEntitySelector);
        if (list.isEmpty()) {
            return false;
        } else {
            Collections.sort(list, this.theNearestAttackableTargetSorter);
            this.targetEntity = list.get(0);
            this.mustUpdate = false;
            this.hunter.onFindTarget(targetEntity);
            return true;
        }
    }

    protected double getFollowDistance() {
        return 16D;
    }


    protected AABB getTargetableArea(double targetDistance) {
        Vec3 renderCenter = new Vec3(this.mob.getX() + 0.5, this.mob.getY()+ 0.5, this.mob.getZ() + 0.5D);
        AABB aabb = new AABB(-radius, -radius, -radius, radius, radius, radius);
        return aabb.move(renderCenter);
    }

    @Override
    public void start() {
        moveTo();
        super.start();
    }

    protected void moveTo(){
        if(walkCooldown > 0){
            walkCooldown--;
        }else{
            this.mob.getNavigation().moveTo(this.targetEntity.getX(), this.targetEntity.getY(), this.targetEntity.getZ(), 1);
            walkCooldown = 30 + this.mob.getRandom().nextInt(40);
        }
    }

    public void stop() {
        super.stop();
        this.mob.getNavigation().stop();
        this.targetEntity = null;
    }

    @Override
    public void tick() {
        super.tick();
        if (this.targetEntity == null || this.targetEntity != null && !this.targetEntity.isAlive()) {
            this.stop();
            this.mob.getNavigation().stop();
        }else{
            moveTo();
        }
        if(targetEntity != null && this.mob.hasLineOfSight(targetEntity) && this.mob.getBbWidth() > 2D && this.mob.onGround()){
            this.mob.getMoveControl().setWantedPosition(targetEntity.getX(), targetEntity.getY(), targetEntity.getZ(), 1);
        }
        if (this.targetEntity != null && this.targetEntity.isAlive() && this.mob.distanceToSqr(this.targetEntity) < this.hunter.getMaxDistToItem() && mob.getItemInHand(InteractionHand.MAIN_HAND).isEmpty()) {
            hunter.onGetItem(targetEntity);
            this.targetEntity.getItem().shrink(1);
            stop();
        }
    }

    public void makeUpdate() {
        this.mustUpdate = true;
    }

    @Override
    public boolean canContinueToUse() {
        boolean path = this.mob.getBbWidth() > 2D ||  !this.mob.getNavigation().isDone();
        return path && targetEntity != null && targetEntity.isAlive();
    }

    public record Sorter(Entity theEntity) implements Comparator<Entity> {
        public int compare(Entity p_compare_1_, Entity p_compare_2_) {
            final double d0 = this.theEntity.distanceToSqr(p_compare_1_);
            final double d1 = this.theEntity.distanceToSqr(p_compare_2_);
            return Double.compare(d0, d1);
        }
    }

}

